$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'import-backup.ps1')
$taskOut=Join-Path 'F:\Agentopia-Acceptance\desktop-recovery-launcher' ([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds().ToString());$null=New-Item -ItemType Directory -Path $taskOut
$checks=[Collections.Generic.List[string]]::new()
function Assert-Refused([scriptblock]$Action,[string]$Pattern){$failed=$false;try{& $Action|Out-Null}catch{if($_.Exception.Message -notmatch $Pattern){throw};$failed=$true};if(-not $failed){throw 'Expected launcher refusal.'}}
function New-Case([string]$Name){$homePath=Join-Path $taskOut $Name;$data=Join-Path $homePath 'AppData\Roaming';$source=Join-Path $homePath 'backup';$null=New-Item -ItemType Directory -Path $data,$source;$descriptor=[ordered]@{format=2;kind='agentopia-desktop-recovery';requiresDesktopRecoveryFormat=2;codex='0.163.0'};$i=0;foreach($field in @('databaseManifest','profileArchive','profileManifest','publicArchive','publicManifest','references')){$name='Generated resource '+$i+'.bin';$i++;$file=Join-Path $source $name;[IO.File]::WriteAllText($file,'GENERATED-'+$field);$descriptor[$field]=@{file=$name;sha256=Get-AgentopiaRecoveryHash $file}};$descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $source 'desktop-recovery.json') -Encoding utf8;return @{home=$homePath;data=$data;source=$source;descriptor=$descriptor}}
$case=New-Case 'fresh';$result=New-AgentopiaDesktopRecoveryRequest $case.source $case.home $case.data @('Ubuntu') -ValidateOnly;if(-not $result.success -or $result.writes -ne 0 -or (Test-Path -LiteralPath (Join-Path $case.home '.agentopia'))){throw 'Check-only wrote recovery state.'};$checks.Add('The full bundle check validates all six resource hashes without writing a request.')
$queued=New-AgentopiaDesktopRecoveryRequest $case.source $case.home $case.data @('Ubuntu');$request=Get-Content -LiteralPath $queued.request -Raw|ConvertFrom-Json;if(-not $queued.queued -or $request.profile -ne (Join-Path $case.data 'Agentopia') -or (Test-Path -LiteralPath $request.profile)){throw 'Queueing created an application profile.'};$checks.Add('Queueing writes only the explicit fresh-profile request, using a new identity.')
$before=Get-AgentopiaRecoveryHash $queued.request;$again=New-AgentopiaDesktopRecoveryRequest $case.source $case.home $case.data @();if(-not $again.alreadyQueued -or $again.writes -ne 0 -or (Get-AgentopiaRecoveryHash $queued.request) -cne $before){throw 'Repeated queueing changed the request.'};$checks.Add('Repeating the same request preserves its identity and bytes.')
Assert-Refused {New-AgentopiaDesktopRecoveryRequest $case.source $case.home $case.data @('AgentopiaRuntime')} 'existing Agentopia runtime';$checks.Add('An existing runtime cannot be bypassed by an already queued request.')
$other=New-Case 'existing';$profile=Join-Path $other.data 'Agentopia';$null=New-Item -ItemType Directory -Path $profile;[IO.File]::WriteAllText((Join-Path $profile 'keep'),'existing');Assert-Refused {New-AgentopiaDesktopRecoveryRequest $other.source $other.home $other.data @()} 'Existing desktop';if([IO.File]::ReadAllText((Join-Path $profile 'keep')) -ne 'existing'){throw 'Existing data changed.'};$checks.Add('Existing desktop data remains unchanged.')
$bad=New-Case 'changed';[IO.File]::AppendAllText((Join-Path $bad.source $bad.descriptor.profileArchive.file),'damaged');Assert-Refused {New-AgentopiaDesktopRecoveryRequest $bad.source $bad.home $bad.data @()} 'missing or changed';if(Test-Path -LiteralPath (Join-Path $bad.home '.agentopia')){throw 'Corruption created a pending request.'};$checks.Add('Changed archive bytes are refused before writing state.')
$bad=New-Case 'traversal';$bad.descriptor.profileArchive.file='../outside';$bad.descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $bad.source 'desktop-recovery.json') -Encoding utf8;Assert-Refused {Read-AgentopiaDesktopRecoveryDescriptor $bad.source} 'Invalid desktop recovery resource';$checks.Add('Escaping resource names cannot enter a queued request.')
foreach($capability in 3..18){
 $legacy=New-Case ('capability-'+$capability);$legacy.descriptor.requiresDesktopRecoveryFormat=$capability
 $fields=@('clipboardArchive','clipboardManifest');if($capability -ge 4){$fields+='settingsManifest'};if($capability -ge 5){$fields+=@('externalArchive','externalManifest')};if($capability -ge 6){$fields+='layoutsManifest'};if($capability -ge 12){$fields+=@('workspaceArchive','workspaceManifest')}
 if($capability -ge 18){$fields+='windowsProfileManifest'}
 foreach($field in $fields){$file=Join-Path $legacy.source ($field+'.bin');[IO.File]::WriteAllText($file,'GENERATED-'+$field);$legacy.descriptor[$field]=@{file=($field+'.bin');sha256=Get-AgentopiaRecoveryHash $file}}
 $legacy.descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $legacy.source 'desktop-recovery.json') -Encoding utf8
 $validation=New-AgentopiaDesktopRecoveryRequest $legacy.source $legacy.home $legacy.data @() -ValidateOnly
 if(-not $validation.success -or $validation.writes -ne 0){throw 'A compatible capability was refused or wrote state.'}
 if($capability -eq 12){$workspace=$legacy}
}
$checks.Add('Every compatible capability through18 validates without creating recovery state.')
$queue12=New-AgentopiaDesktopRecoveryRequest $workspace.source $workspace.home $workspace.data @();if(-not $queue12.queued){throw 'Workspace recovery was not queued.'};$request12=Get-Content -LiteralPath $queue12.request -Raw|ConvertFrom-Json;if($request12.descriptorSha256 -cne (Get-AgentopiaRecoveryHash (Join-Path $workspace.source 'desktop-recovery.json'))){throw 'Workspace recovery was not bound to the exact descriptor.'};$checks.Add('Capability12 queues the sealed workspace bundle while leaving the destination profile absent.')
foreach($field in @('workspaceArchive','workspaceManifest')){
 $file=Join-Path $workspace.source $workspace.descriptor[$field].file;$bytes=[IO.File]::ReadAllBytes($file);[IO.File]::AppendAllText($file,'DAMAGED');Assert-Refused {Read-AgentopiaDesktopRecoveryDescriptor $workspace.source} 'missing or changed';[IO.File]::WriteAllBytes($file,$bytes)
 $entry=$workspace.descriptor[$field];$workspace.descriptor.Remove($field);$workspace.descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $workspace.source 'desktop-recovery.json') -Encoding utf8;Assert-Refused {Read-AgentopiaDesktopRecoveryDescriptor $workspace.source} 'Invalid desktop recovery resource';$workspace.descriptor[$field]=$entry
}
$checks.Add('Both workspace resources are mandatory and checked by their exact byte hashes.')
foreach($capability in @(11,19)){$workspace.descriptor.requiresDesktopRecoveryFormat=$capability;$workspace.descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $workspace.source 'desktop-recovery.json') -Encoding utf8;Assert-Refused {Read-AgentopiaDesktopRecoveryDescriptor $workspace.source} 'newer recovery capability|compatible Agentopia'}
$workspace.descriptor.requiresDesktopRecoveryFormat=12;$workspace.descriptor|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $workspace.source 'desktop-recovery.json') -Encoding utf8;$checks.Add('Downgraded workspace metadata and future formats are refused.')
foreach($name in @('BACKUP-INCOMPLETE.txt','WORKSPACE-BACKUP-INCOMPLETE.txt')){$marker=Join-Path $workspace.source $name;[IO.File]::WriteAllText($marker,'GENERATED INCOMPLETE');Assert-Refused {Read-AgentopiaDesktopRecoveryDescriptor $workspace.source} 'incomplete';[IO.File]::Delete($marker)};$checks.Add('An incomplete backup cannot enter recovery even when the other resource hashes match.')
$receipt=@{success=$true;out=$taskOut;checks=@($checks);groups=$checks.Count;request=$queued.request;home=$case.home;appData=$case.data;profile=$request.profile;workspaceRequest=$queue12.request;helperSha256=Get-AgentopiaRecoveryHash (Join-Path $PSScriptRoot 'import-backup.ps1');productionChanged=$false;providerRequests=0};$receipt|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $taskOut 'evidence.json') -Encoding utf8;$receipt|ConvertTo-Json -Depth 6 -Compress
